import { useState, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import Swal from "sweetalert2";

export default function Scan() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [view, setView] = useState("scanner"); // "scanner" | "list"
  const [image, setImage] = useState(null);
  const [imageFile, setImageFile] = useState(null);
  const [cameraOpen, setCameraOpen] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [scans, setScans] = useState([]);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const fileInputRef = useRef(null);
  const streamRef = useRef(null);

  const storageKey = `scans_${user?.uid || user?.email || "guest"}`;

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem(storageKey) || "[]");
    setScans(saved);
  }, [user]);

  const openCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "environment" },
      });
      streamRef.current = stream;
      setCameraOpen(true);
      setTimeout(() => {
        if (videoRef.current) videoRef.current.srcObject = stream;
      }, 100);
    } catch (err) {
      Swal.fire({
        title: "No se pudo acceder a la cámara",
        text: "Verifica los permisos de cámara en tu navegador.",
        icon: "error",
        confirmButtonColor: "#3d5e35",
        background: "#f5f2ec",
        customClass: { popup: "rounded-3xl" },
      });
    }
  };

  const closeCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
    }
    setCameraOpen(false);
  };

  const capturePhoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    canvas.toBlob((blob) => {
      const file = new File([blob], "captura.jpg", { type: "image/jpeg" });
      setImageFile(file);
      setImage(URL.createObjectURL(blob));
      closeCamera();
    }, "image/jpeg");
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (!file.type.startsWith("image/")) {
      Swal.fire({
        title: "Archivo no válido",
        text: "Por favor selecciona una imagen.",
        icon: "warning",
        confirmButtonColor: "#3d5e35",
        background: "#f5f2ec",
        customClass: { popup: "rounded-3xl" },
      });
      return;
    }
    setImageFile(file);
    setImage(URL.createObjectURL(file));
  };

  const handleDrop = (e) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (!file || !file.type.startsWith("image/")) return;
    setImageFile(file);
    setImage(URL.createObjectURL(file));
  };

  const resetImage = () => {
    setImage(null);
    setImageFile(null);
  };

  const toBase64 = (file) =>
    new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result);
      reader.onerror = reject;
    });

  const analyzeImage = async () => {
    if (!imageFile) return;
    setAnalyzing(true);
    try {
      const base64Image = await toBase64(imageFile);
      const newScan = {
        id: Date.now(),
        enfermedad: "Sigatoka Negra",
        nivel_riesgo: "Alto",
        confianza: 94.5,
        planta: "Banano",
        fecha: new Date().toLocaleDateString("es-EC", {
          day: "2-digit",
          month: "short",
          year: "numeric",
        }),
        imageUrl: base64Image,
        badge: "bg-red-50 text-red-600",
      };

      const prevScans = JSON.parse(localStorage.getItem(storageKey) || "[]");
      prevScans.unshift(newScan);
      const updated = prevScans.slice(0, 20);
      localStorage.setItem(storageKey, JSON.stringify(updated));
      setScans(updated);

      setAnalyzing(false);
      navigate("/result", {
        state: { result: null, imageUrl: base64Image, scanId: newScan.id },
      });
    } catch (err) {
      setAnalyzing(false);
      Swal.fire({
        title: "Error",
        text: "No se pudo procesar la imagen.",
        icon: "error",
        confirmButtonColor: "#3d5e35",
      });
    }
  };

  const handleDelete = (id) => {
    Swal.fire({
      title: "¿Eliminar escaneo?",
      text: "Esta acción no se puede deshacer.",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#e24b4a",
      cancelButtonColor: "#9ca3af",
      confirmButtonText: "Sí, eliminar",
      cancelButtonText: "Cancelar",
      background: "#f5f2ec",
      customClass: { popup: "rounded-3xl" },
    }).then((result) => {
      if (result.isConfirmed) {
        const updated = scans.filter((s) => s.id !== id);
        setScans(updated);
        localStorage.setItem(storageKey, JSON.stringify(updated));
        Swal.fire({
          title: "Eliminado",
          icon: "success",
          timer: 1200,
          showConfirmButton: false,
          background: "#f5f2ec",
          customClass: { popup: "rounded-3xl" },
        });
      }
    });
  };

  const riskConfig = {
    Alto: { badge: "bg-red-50 text-red-600", dot: "bg-red-500" },
    Medio: { badge: "bg-amber-50 text-amber-700", dot: "bg-amber-500" },
    Bajo: { badge: "bg-green-50 text-green-700", dot: "bg-green-500" },
    Ninguno: { badge: "bg-green-50 text-green-700", dot: "bg-green-500" },
  };

  return (
    <div className="min-h-screen bg-[#f4f7f1] flex flex-col">

      {/* CÁMARA EN VIVO */}
      {cameraOpen && (
        <div className="fixed inset-0 bg-black z-50 flex flex-col">
          <div className="flex items-center gap-3 px-4 py-3 bg-black/60">
            <button
              onClick={closeCamera}
              className="w-9 h-9 rounded-full bg-white/20 text-white flex items-center justify-center text-lg"
            >
              ✕
            </button>
            <span className="text-white text-sm font-medium">Enfoca la hoja</span>
          </div>
          <video ref={videoRef} autoPlay playsInline className="flex-1 w-full object-cover" />
          <canvas ref={canvasRef} className="hidden" />
          <div className="bg-black/70 p-6 flex items-center justify-center gap-10">
            <button
              onClick={closeCamera}
              className="w-12 h-12 rounded-full bg-white/20 text-white text-xl flex items-center justify-center"
            >
              ←
            </button>
            <button
              onClick={capturePhoto}
              className="rounded-full bg-white border-4 border-white/40 shadow-lg"
              style={{ width: 72, height: 72 }}
            />
            <div className="w-12 h-12" />
          </div>
        </div>
      )}

      {/* NAVBAR */}
      <header className="bg-white border-b border-gray-100 px-4 sm:px-6 py-3 flex items-center gap-3 sticky top-0 z-20 shadow-sm">
        <button
          onClick={() => navigate("/home")}
          className="w-9 h-9 rounded-full bg-gray-100 flex items-center justify-center hover:bg-gray-200 transition shrink-0"
        >
          ←
        </button>
        <div className="flex items-center gap-2 flex-1 min-w-0">
          <div className="w-8 h-8 rounded-lg bg-green-700 flex items-center justify-center text-white text-sm shrink-0">
            🌿
          </div>
          <div className="min-w-0">
            <h1 className="font-bold text-sm leading-tight">
              {view === "scanner" ? "Escanear planta" : "Mis escaneos"}
            </h1>
            <p className="text-xs text-gray-500 hidden sm:block">
              {view === "scanner"
                ? "Detección de Sigatoka negra"
                : `${scans.length} escaneo${scans.length !== 1 ? "s" : ""} registrado${scans.length !== 1 ? "s" : ""}`}
            </p>
          </div>
        </div>
      </header>

      {/* TABS */}
      <div className="bg-white border-b border-gray-100 px-4 sm:px-6">
        <div className="flex max-w-6xl mx-auto">
          <button
            onClick={() => setView("scanner")}
            className={`flex-1 sm:flex-none px-5 py-3 text-sm font-semibold border-b-2 transition ${
              view === "scanner"
                ? "border-green-700 text-green-700"
                : "border-transparent text-gray-400 hover:text-gray-600"
            }`}
          >
            📷 Escanear
          </button>
          <button
            onClick={() => setView("list")}
            className={`flex-1 sm:flex-none px-5 py-3 text-sm font-semibold border-b-2 transition ${
              view === "list"
                ? "border-green-700 text-green-700"
                : "border-transparent text-gray-400 hover:text-gray-600"
            }`}
          >
            🗂️ Mis escaneos {scans.length > 0 && `(${scans.length})`}
          </button>
        </div>
      </div>

      {/* VISTA ESCANER */}
      {view === "scanner" && (
        <main className="flex-1 max-w-6xl mx-auto w-full px-4 sm:px-6 py-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

            <div className="flex flex-col gap-4">
              {!image ? (
                <div
                  onDrop={handleDrop}
                  onDragOver={(e) => e.preventDefault()}
                  className="bg-white rounded-3xl p-6 sm:p-8 border-2 border-dashed border-green-200
                             flex flex-col items-center justify-center gap-4
                             hover:border-green-400 hover:bg-green-50/30 transition cursor-pointer min-h-[320px] sm:min-h-[380px]"
                  onClick={() => fileInputRef.current.click()}
                >
                  <div className="w-16 h-16 rounded-2xl bg-green-100 flex items-center justify-center text-3xl">
                    📷
                  </div>
                  <div className="text-center">
                    <h3 className="font-bold text-base text-gray-800 mb-1">
                      Arrastra tu imagen aquí
                    </h3>
                    <p className="text-sm text-gray-500">
                      o haz clic para seleccionar un archivo
                    </p>
                    <p className="text-xs text-gray-400 mt-1">
                      Formatos: JPG, PNG, WEBP — Máx. 10MB
                    </p>
                  </div>
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept="image/*"
                    onChange={handleFileChange}
                    className="hidden"
                  />
                </div>
              ) : (
                <div className="bg-white rounded-3xl overflow-hidden relative min-h-[320px] sm:min-h-[380px]">
                  <img
                    src={image}
                    alt="Vista previa"
                    className="w-full h-full object-cover"
                    style={{ minHeight: 320 }}
                  />
                  <button
                    onClick={resetImage}
                    className="absolute top-4 right-4 w-9 h-9 rounded-full bg-black/50 text-white
                               flex items-center justify-center hover:bg-black/70 transition text-lg"
                  >
                    ✕
                  </button>
                  <div className="absolute bottom-4 left-4 bg-black/50 text-white text-xs px-3 py-1.5 rounded-full">
                    ✅ Imagen cargada
                  </div>
                </div>
              )}

              <div className="flex gap-3">
                <button
                  onClick={openCamera}
                  className="flex-1 bg-green-700 hover:bg-green-800 transition text-white py-3
                             rounded-2xl text-sm font-semibold flex items-center justify-center gap-2"
                >
                  📸 Usar cámara
                </button>
                <button
                  onClick={() => fileInputRef.current.click()}
                  className="flex-1 bg-white border-2 border-green-200 hover:bg-green-50
                             transition text-green-700 py-3 rounded-2xl text-sm font-semibold
                             flex items-center justify-center gap-2"
                >
                  🖼️ Subir foto
                </button>
              </div>

              {image && (
                <button
                  onClick={analyzeImage}
                  disabled={analyzing}
                  className="w-full bg-green-700 hover:bg-green-800 transition text-white py-4
                             rounded-2xl text-base font-bold flex items-center justify-center gap-3
                             disabled:opacity-60 shadow-sm"
                >
                  {analyzing ? (
                    <>
                      <span className="w-5 h-5 border-2 border-white/40 border-t-white rounded-full animate-spin" />
                      Analizando imagen...
                    </>
                  ) : (
                    <>🔍 Analizar planta</>
                  )}
                </button>
              )}
            </div>

            <div className="flex flex-col gap-4">
              <div className="bg-white rounded-3xl p-5 sm:p-6">
                <h2 className="font-bold text-base text-gray-800 mb-4">
                  💡 Consejos para una mejor detección
                </h2>
                <div className="space-y-3">
                  {[
                    { icon: "☀️", title: "Buena iluminación", desc: "Usa luz natural directa, evita sombras sobre la hoja" },
                    { icon: "🎯", title: "Enfoque correcto", desc: "La hoja debe estar nítida y ocupar la mayor parte de la imagen" },
                    { icon: "📐", title: "Una hoja a la vez", desc: "Centra una sola hoja para un resultado más preciso" },
                    { icon: "🚫", title: "Sin movimiento", desc: "Mantén el dispositivo estable al tomar la foto" },
                  ].map((tip, i) => (
                    <div key={i} className="flex items-start gap-3 p-3 bg-green-50/50 rounded-2xl">
                      <span className="text-xl shrink-0">{tip.icon}</span>
                      <div>
                        <p className="text-sm font-semibold text-gray-800">{tip.title}</p>
                        <p className="text-xs text-gray-500 mt-0.5">{tip.desc}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="bg-white rounded-3xl p-5 sm:p-6">
                <h2 className="font-bold text-base text-gray-800 mb-4">
                  🍃 ¿Qué enfermedades detectamos?
                </h2>
                <div className="space-y-2">
                  {[
                    { name: "Sigatoka Negra", level: "Alto riesgo", color: "bg-red-50 text-red-600", dot: "bg-red-500" },
                    { name: "Sigatoka Amarilla", level: "Riesgo medio", color: "bg-amber-50 text-amber-700", dot: "bg-amber-500" },
                    { name: "Mancha Foliar", level: "Riesgo medio", color: "bg-amber-50 text-amber-700", dot: "bg-amber-500" },
                    { name: "Hoja Sana", level: "Sin riesgo", color: "bg-green-50 text-green-700", dot: "bg-green-500" },
                  ].map((disease, i) => (
                    <div key={i} className="flex items-center justify-between p-3 rounded-2xl border border-gray-100 hover:bg-gray-50 transition">
                      <div className="flex items-center gap-2.5">
                        <span className={`w-2.5 h-2.5 rounded-full shrink-0 ${disease.dot}`} />
                        <span className="text-sm font-medium text-gray-800">{disease.name}</span>
                      </div>
                      <span className={`text-xs font-semibold px-2.5 py-1 rounded-full ${disease.color}`}>
                        {disease.level}
                      </span>
                    </div>
                  ))}
                </div>
              </div>

              <div className="bg-amber-50 border border-amber-100 rounded-3xl p-4 flex items-start gap-3">
                <span className="text-xl shrink-0">⚠️</span>
                <p className="text-xs text-amber-800">
                  Esta herramienta es de apoyo para agricultores. Para decisiones críticas, consulta siempre con un agrónomo especialista.
                </p>
              </div>
            </div>
          </div>
        </main>
      )}

      {/* VISTA LISTA */}
      {view === "list" && (
        <main className="flex-1 max-w-4xl mx-auto w-full px-4 sm:px-6 py-6">
          {scans.length === 0 ? (
            <div className="bg-white rounded-3xl p-10 flex flex-col items-center justify-center gap-4 text-center">
              <span className="text-6xl">🍃</span>
              <h2 className="font-bold text-lg text-gray-800">No tienes escaneos aún</h2>
              <p className="text-sm text-gray-500 max-w-xs">
                Toma una foto de una hoja de banano para detectar si tiene Sigatoka negra.
              </p>
              <button
                onClick={() => setView("scanner")}
                className="bg-green-700 hover:bg-green-800 transition text-white px-6 py-3 rounded-2xl text-sm font-semibold"
              >
                📷 Hacer mi primer escaneo
              </button>
            </div>
          ) : (
            <div className="space-y-3">
              {scans.map((item) => {
                const risk = riskConfig[item.nivel_riesgo] || riskConfig["Medio"];
                return (
                  <div
                    key={item.id}
                    className="bg-white rounded-2xl border border-gray-100 overflow-hidden flex hover:shadow-sm transition"
                  >
                    <button
                      onClick={() =>
                        navigate("/result", {
                          state: {
                            result: null,
                            imageUrl: item.imageUrl,
                            scanId: item.id,
                          },
                        })
                      }
                      className="flex items-center gap-4 flex-1 p-3 sm:p-4 text-left"
                    >
                      {item.imageUrl ? (
                        <img
                          src={item.imageUrl}
                          alt={item.enfermedad}
                          className="w-16 h-16 sm:w-20 sm:h-20 rounded-xl object-cover shrink-0"
                        />
                      ) : (
                        <div className="w-16 h-16 sm:w-20 sm:h-20 rounded-xl bg-green-50 flex items-center justify-center text-2xl shrink-0">
                          🍃
                        </div>
                      )}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap mb-1">
                          <span className={`w-2 h-2 rounded-full shrink-0 ${risk.dot}`} />
                          <h3 className="font-semibold text-sm sm:text-base text-gray-800 truncate">
                            {item.enfermedad}
                          </h3>
                          <span className={`text-xs font-semibold px-2 py-0.5 rounded-full ${risk.badge}`}>
                            {item.nivel_riesgo}
                          </span>
                        </div>
                        <p className="text-xs text-gray-500 truncate">
                          {item.planta} · {item.fecha}
                        </p>
                        <p className="text-xs text-gray-400 mt-0.5">
                          Confianza: {item.confianza}%
                        </p>
                      </div>
                      <span className="text-gray-300 text-lg shrink-0">›</span>
                    </button>

                    <button
                      onClick={() => handleDelete(item.id)}
                      className="border-l border-gray-100 px-4 text-gray-300 hover:text-red-500 hover:bg-red-50 transition flex items-center justify-center shrink-0"
                      title="Eliminar"
                    >
                      🗑️
                    </button>
                  </div>
                );
              })}
            </div>
          )}
        </main>
      )}

    </div>
  );
}
